package com.valorant.tracker.model;
import jakarta.persistence.*; import java.time.OffsetDateTime;
@Entity @Table(name="snapshots") public class Snapshot { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; OffsetDateTime timestamp; long youtubeViewers,twitchViewers,kickViewers,combinedViewers; int youtubeStreams,twitchStreams,kickStreams; protected Snapshot(){} public Snapshot(OffsetDateTime t,long y,long tw,long k,int yc,int tc,int kc){timestamp=t;youtubeViewers=y;twitchViewers=tw;kickViewers=k;combinedViewers=y+tw+k;youtubeStreams=yc;twitchStreams=tc;kickStreams=kc;} public Long getId(){return id;} public OffsetDateTime getTimestamp(){return timestamp;} public long getYoutubeViewers(){return youtubeViewers;} public long getTwitchViewers(){return twitchViewers;} public long getKickViewers(){return kickViewers;} public long getCombinedViewers(){return combinedViewers;} public int getYoutubeStreams(){return youtubeStreams;} public int getTwitchStreams(){return twitchStreams;} public int getKickStreams(){return kickStreams;} }
